practice.solution:
#include <cassert>
#include <cmath>
#include <iostream>

double fallSeconds(double height, double gravity)
{
    assert(gravity > 0.0 && "Gravity must point toward the ground");
    if (height <= 0.0) return 0.0;
    return std::sqrt(2.0 * height / gravity);
}

int main()
{
    std::cout << fallSeconds(20.0, 10.0) << '\n';
    return 0;
}

