#define main learner_main
#include "main.cpp"
#undef main
#include <cerrno>
#include <csignal>
#include <iostream>
#include <sys/resource.h>
#include <sys/wait.h>
#include <unistd.h>

bool aborts(double height, double gravity)
{
    const pid_t child{fork()};
    if (child == -1) { std::cerr << "fork failed\n"; return false; }
    if (child == 0)
    {
        const rlimit limit{0, 0};
        if (setrlimit(RLIMIT_CORE, &limit) != 0) _exit(120);
        (void)fallSeconds(height, gravity);
        _exit(0);
    }
    int status{};
    pid_t result;
    do { result = waitpid(child, &status, 0); } while (result == -1 && errno == EINTR);
    return result == child && WIFSIGNALED(status) && WTERMSIG(status) == SIGABRT;
}

int main()
{
#ifdef NDEBUG
    std::cerr << "This test requires -UNDEBUG\n";
    return 1;
#endif
    int failures{};
    const double heights[]{20.0, 45.0, 5.0, 0.0, -7.0};
    const double gravities[]{10.0, 10.0, 10.0, 10.0, 2.0};
    const double expected[]{2.0, 3.0, 1.0, 0.0, 0.0};
    for (int i{}; i < 5; ++i)
    {
        const double actual{fallSeconds(heights[i], gravities[i])};
        if (!std::isfinite(actual) || std::abs(actual - expected[i]) > 1e-10)
        { std::cerr << "Wrong fall time at case " << i << '\n'; ++failures; }
    }
    for (double height : {20.0, 0.0, -7.0})
        for (double gravity : {0.0, -10.0})
            if (!aborts(height, gravity))
            { std::cerr << "Expected assertion abort for height " << height << " gravity " << gravity << '\n'; ++failures; }
    return failures == 0 ? 0 : 1;
}

