practice.solution:
#include <cassert>
#include <iostream>

int recordVisit(int& visits)
{
    assert(visits >= 0 && visits < 1000);
    ++visits;
    return visits;
}

int main()
{
    int visits{4};
    std::cout << recordVisit(visits) << '\n';
    return 0;
}

