#define main learner_main
#include "main.cpp"
#undef main
#include <iostream>
#ifndef NDEBUG
#include <cerrno>
#include <csignal>
#include <sys/resource.h>
#include <sys/wait.h>
#include <unistd.h>

bool aborts(int initial)
{
    const pid_t child{fork()};
    if (child == -1) { std::cerr << "fork failed\n"; return false; }
    if (child == 0)
    {
        const rlimit limit{0, 0};
        if (setrlimit(RLIMIT_CORE, &limit) != 0) _exit(120);
        int visits{initial};
        (void)recordVisit(visits);
        _exit(0);
    }
    int status{};
    pid_t result;
    do { result = waitpid(child, &status, 0); } while (result == -1 && errno == EINTR);
    return result == child && WIFSIGNALED(status) && WTERMSIG(status) == SIGABRT;
}
#endif

int main()
{
    int failures{};
    for (int initial : {0, 4, 57, 998, 999})
    {
        int visits{initial};
        const int returned{recordVisit(visits)};
        if (visits != initial + 1 || returned != initial + 1)
        { std::cerr << "Expected exactly one visit after " << initial << '\n'; ++failures; }
    }
    int visits{};
    for (int expected{1}; expected <= 1000; ++expected)
    {
        const int returned{recordVisit(visits)};
        if (visits != expected || returned != expected)
        { std::cerr << "Sequence failed at " << expected << '\n'; ++failures; break; }
    }
#ifndef NDEBUG
    for (int initial : {-1, 1000})
        if (!aborts(initial))
        { std::cerr << "Expected assertion abort for starting visits " << initial << '\n'; ++failures; }
#endif
    return failures == 0 ? 0 : 1;
}

